mapper.select:
SELECT COUNT(*)
FROM community_follow
WHERE follower_id = #{viewer}
  AND following = 1
  AND (target_key = #{key}
      OR target_key IN (
        SELECT CONCAT('b',id)
        FROM community_blogger
        WHERE user_id = #{userId}
          AND enabled = 1))

SELECT COUNT(*)
FROM community_follow
WHERE follower_id = #{viewer}
  AND target_key = #{key}
  AND following = 1

mapper.delete:
DELETE
FROM community_notification
WHERE recipient_id = #{recipient}
  AND actor_id = #{actor}
  AND kind = 'FOLLOW'

mapper.select:
SELECT f.target_key

ORDER BY f.updated_at DESC,f.target_key
LIMIT #{limit}
OFFSET #{offset}
